// DateFormatSymbols.getZoneStrings() rows (names 1-4) of every ACF 2023 setLocale name and the ZoneInfo data of their
// zones, generated from the ACF JVM (Java 17.0.21.0.3); do not edit.
import type { JavaZone } from './java-calendar.js';

/** A java.util.TimeZone a zone name selects: getDSTSavings() and its ZoneInfo raw offset before and from each wall time on. */
export interface NamedZone {
  readonly id: string;
  /** The zone its rules resolve a wall time in: the IANA zone, or the fixed offset of a zone without transitions. */
  readonly rules: JavaZone;
  readonly dstMs: number;
  readonly rawMs: number;
  readonly rawFrom: readonly (readonly [wall: number, rawMs: number])[];
}

/** A getZoneStrings() row: its zone and names 1-4 (long and short standard, long and short daylight). */
export interface ZoneRow {
  readonly zone: NamedZone;
  readonly names: readonly string[];
}

/** A locale's rows in getZoneStrings() order, and the row of each zone ID. */
export interface ZoneTable {
  readonly rows: readonly ZoneRow[];
  readonly byId: ReadonlyMap<string, ZoneRow>;
}

