const TABLE_BY_NAME: ReadonlyMap<string, number> = new Map(
  ZONE_TABLES.flatMap(([locales], index) => locales.split('|').map((name) => [name.toLowerCase(), index] as const)),
);
let zones: readonly NamedZone[] | undefined;
let zoneNames: readonly string[] | undefined;
const decodedTables = new Map<number, ZoneTable>();

function at<T>(list: readonly T[], index: number): T {
  const value = list[index];
  if (value === undefined) throw new RangeError(`Missing zone name data at ${index}`);
  return value;
}

/** Base-36 number of `width` digits at index `i` of a packed string. */
const packed = (s: string, width: number, i: number): number => parseInt(s.slice(i * width, i * width + width), 36);

/** Every zone of ZONE_IDS in order. */
function decodeZones(): readonly NamedZone[] {
  const raws = ZONE_RAW.split('|');
  const ms = (seconds: string): number => parseInt(seconds, 36) * 1000;
  return ZONE_IDS.split('|').map((id, i): NamedZone => {
    const [current, ...changes] = at(raws, i).split(' ');
    const rawMs = ms(current ?? '');
    const rawFrom = changes.map((change): [number, number] => {
      const [wall = '', raw = ''] = change.split(':');
      return [ms(wall), ms(raw)];
    });
    return { id, rules: rawFrom.length === 0 ? rawMs : id, dstMs: Number(ZONE_DST.charAt(i)) * 1_800_000, rawMs, rawFrom };
  });
}

/** ZONE_NAMES with each name's shared prefix restored. */
function decodeNames(): readonly string[] {
  let previous = '';
  return ZONE_NAMES.split('|').map((entry) => (previous = previous.slice(0, parseInt(entry.charAt(0), 36)) + entry.slice(1)));
}

/** The getZoneStrings() rows SimpleDateFormat reads under setLocale(`name`) (in any case); undefined for a name it refuses. */
export function javaZoneTable(name: string): ZoneTable | undefined {
  const index = TABLE_BY_NAME.get(name.toLowerCase());
  if (index === undefined) return undefined;
  let table = decodedTables.get(index);
  if (table === undefined) {
    const all = (zones ??= decodeZones());
    const names = (zoneNames ??= decodeNames());
    const [, order, refs] = at(ZONE_TABLES, index);
    const ids = at(ZONE_ORDERS, order);
    const rows = Array.from({ length: refs.length / 3 }, (_, k): ZoneRow => {
      const set = packed(refs, 3, k) * 4;
      return { zone: at(all, packed(ids, 2, k)), names: [0, 1, 2, 3].map((n) => at(names, packed(ZONE_NAME_SETS, 3, set + n))) };
    });
    const byId = new Map<string, ZoneRow>();
    for (const row of rows) if (!byId.has(row.zone.id)) byId.set(row.zone.id, row);
    table = { rows, byId };
    decodedTables.set(index, table);
  }
  return table;
}
